function tokenUser(PDO $p): ?array { $h=getallheaders(); $t=''; if(!empty($h['Authorization'])&&preg_match('/Bearer\s+(.+)/i',$h['Authorization'],$m))$t=trim($m[1]); if(!$t && !empty($_SESSION['token']))$t=$_SESSION['token']; if(!$t)return null; $s=$p->prepare('SELECT role,user_id FROM api_tokens WHERE token_hash=? AND expires_at>NOW()');$s->execute([hash('sha256',$t)]);$r=$s->fetch(); if(!$r)return null; $u=['role'=>$r['role'],'id'=>$r['user_id']]; if($u['role']==='admin')$u['fullName']='Administrator'; elseif($u['role']==='examiner'){$q=$p->prepare('SELECT full_name,email FROM examiners WHERE id=?');$q->execute([$u['id']]);$x=$q->fetch();if(!$x)return null;$u['fullName']=$x['full_name'];$u['email']=$x['email'];}else{$q=$p->prepare('SELECT full_name,email,student_id,course,year,status FROM students WHERE id=?');$q->execute([$u['id']]);$x=$q->fetch();if(!$x)return null;$u['fullName']=$x['full_name'];$u['email']=$x['email'];$u['studentId']=$x['student_id'];$u['course']=$x['course'];$u['year']=$x['year'];$u['status']=$x['status'];} return $u; }
