function requireOwner(array $u,array $e): void {if($u['role']==='examiner' && $e['examiner_id']!==$u['id'])out(['error'=>'You do not have access to this examination.'],403);}
function spreadsheetRows(string $file, string $ext): array {
 if(in_array($ext,['xlsx','xls'],true)) {
  if(!class_exists('\\PhpOffice\\PhpSpreadsheet\\IOFactory')) out(['error'=>'Excel upload requires PhpSpreadsheet. Run composer install in the ExamPro folder; see README.'],400);
  try {
   $book=\PhpOffice\PhpSpreadsheet\IOFactory::load($file);
   $sheet=$book->getActiveSheet();
   $data=$sheet->toArray('',true,true,false);
   $tmp=tempnam(sys_get_temp_dir(),'exampro_');
   $fp=fopen($tmp,'w');
   foreach($data as $row) fputcsv($fp,$row);
   fclose($fp);
   $parsed=csvRows($tmp); unlink($tmp); return $parsed;
  } catch(Throwable $e) { out(['error'=>'Could not read this Excel file. Check that it is a valid .xls or .xlsx workbook.'],400); }
 }
 return csvRows($file);
}
function csvRows(string $file): array {$f=fopen($file,'r');if(!$f)return []; $first=fgets($f);if($first===false){fclose($f);return [];} $delims=[',',';',"\t"];$delimiter=',';$max=-1;foreach($delims as $d){$n=count(str_getcsv(trim($first),$d));if($n>$max){$max=$n;$delimiter=$d;}}rewind($f);$headers=fgetcsv($f,0,$delimiter);$rows=[];while(($r=fgetcsv($f,0,$delimiter))!==false){if(count($r)==1&&trim((string)$r[0])==='')continue;$row=[];foreach($headers as $i=>$h)$row[preg_replace('/[^a-z0-9]/','',strtolower(trim((string)$h)))]=trim((string)($r[$i]??''));$get=function(...$keys)use($row){foreach($keys as $k){$k=preg_replace('/[^a-z0-9]/','',strtolower($k));if(isset($row[$k])&&$row[$k]!=='')return $row[$k];}return '';};$opts=[];foreach(['A','B','C','D'] as $i=>$letter){$num=$i+1;$opts[]=$get('option'.$letter,$letter,'choice'.$letter,$letter.'option','option'.$num,'choice'.$num,'answeroption'.$letter);} $answer=strtoupper(preg_replace('/^OPTION\s*/i','',$get('correctanswer','correctoption','answer','answerkey','rightanswer')));$marks=$get('marks','mark','points');$marks=$marks===''?1:(float)$marks;$question=$get('question','questions','questiontext','mcq');$err='';if(!$question)$err='Question is required.';elseif(count(array_filter($opts))!==4)$err='Options A-D are missing.';elseif(!in_array($answer,['A','B','C','D'],true))$err='Correct Answer must be A, B, C, or D.';elseif($marks<=0)$err='Marks must be positive.';$rows[]=$err?['error'=>$err]:['question'=>$question,'options'=>$opts,'answer'=>$answer,'marks'=>$marks];}fclose($f);return $rows;}
